+package com.example.contact;
+
+import java.util.ArrayList;
+import java.util.LinkedList;
+import java.util.List;
+
+import org.springframework.stereotype.Service;
+
+/**
+ * Keeps the sent messages in memory for the lifetime of the application,
+ * shared by every user and every visit to the contact view.
+ */
+@Service
+public class ContactMessageService {
+
+    private final LinkedList<ContactMessage> messages = new LinkedList<>();
+
+    public synchronized void send(ContactMessage message) {
+        messages.addFirst(message);
+    }
+
+    /** Returns the sent messages, newest first. */
+    public synchronized List<ContactMessage> findAll() {
+        return new ArrayList<>(messages);
+    }
+}
